```bash
cd /home/vscode/nullness-benchmarks/wala-util && sed -i '258,282c\    int[] cr = null; // allocate on demand
    int ci = 0;

    while (ai < al && bi < bl) {
      int cmp = (ar[ai] - br[bi]);

      // (accept element only on a match)
      if (cmp > 0) { // a greater
        bi++;
      } else if (cmp < 0) { // b greater
        ai++;
      } else {
        if (cr == null) {
          cr = new int[al]; // allocate enough (i.e. too much)
        }
        cr[ci++] = ar[ai];
        ai++;
        bi++;
      }
    }

    // now compact cr to "just enough"
    size = ci;
    if (ci == 0) {
      elements = new int[0];
    } else if (cr != null && ci != cr.length) {
      int[] result = new int[ci];
      System.arraycopy(cr, 0, result, 0, ci);
      elements = result;
    } else {
      // cr is non-null and fully utilized
      elements = (cr == null) ? new int[0] : cr;
    }
    return;' src/main/java/com/ibm/wala/util/intset/MutableSparseIntSet.java && ./gradlew compileJava -x test -q > new_build_output.log 2>&1 && grep -n "NullAway: .*errors" new_build_output.log || tail -n 80 new_build_output.log```

